import { readFileSync } from "node:fs";
import { runScenario, type Scenario } from "./claimOffice.js";

const scenario = JSON.parse(readFileSync(0, "utf8")) as Scenario;
process.stdout.write(JSON.stringify({ results: runScenario(scenario) }));
import { payoutCap, settleClaim, type ClaimResult, type Damage } from "./claimSettlement.js";
import type { Item } from "./itemCatalog.js";
import { quotePremium, type Customer } from "./premiumQuote.js";

export type { ClaimResult, Customer, Damage, Item };

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export interface Scenario {
  customer: Customer;
  steps: (QuoteStep | ClaimStep)[];
}

export type QuoteResult = { premium: number };
export type Result = QuoteResult | ClaimResult;

function isFollowUpContract(earlierSteps: Scenario["steps"]): boolean {
  return earlierSteps.some((step) => step.op === "quote");
}

function referencedPolicy(steps: Scenario["steps"], claim: ClaimStep): QuoteStep {
  return steps[claim.policy] as QuoteStep;
}

function processClaim(steps: Scenario["steps"], remainingCaps: Map<number, number>, claim: ClaimStep): ClaimResult {
  const policy = referencedPolicy(steps, claim);
  const remainingCap = remainingCaps.get(claim.policy) ?? payoutCap(policy.items);
  const result = settleClaim(remainingCap, policy.items, claim.incident.damages);
  remainingCaps.set(claim.policy, result.remainingCap);
  return result;
}

export function runScenario(scenario: Scenario): Result[] {
  const remainingCaps = new Map<number, number>();
  return scenario.steps.map((step, index) => {
    if (step.op === "claim") {
      return processClaim(scenario.steps, remainingCaps, step);
    }
    const followUpContract = isFollowUpContract(scenario.steps.slice(0, index));
    return { premium: quotePremium(scenario.customer, followUpContract, step.items) };
  });
}
export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface PriceListEntry {
  insuranceValue: number;
  basePremium: number;
}

const MAIN_ITEM_PRICE_LIST: Record<string, PriceListEntry> = {
  sword: { insuranceValue: 1000, basePremium: 100 },
  amulet: { insuranceValue: 600, basePremium: 60 },
  staff: { insuranceValue: 800, basePremium: 80 },
  potion: { insuranceValue: 400, basePremium: 40 },
};
export const COMPONENT_TYPES = ["rune", "moonstone"];
export const COMPONENT_PRICE: PriceListEntry = { insuranceValue: 250, basePremium: 25 };

export function isComponent(item: Item): boolean {
  return COMPONENT_TYPES.includes(item.type);
}

export function priceListEntry(item: Item): PriceListEntry {
  if (isComponent(item)) {
    return COMPONENT_PRICE;
  }
  const entry = MAIN_ITEM_PRICE_LIST[item.type];
  if (!entry) {
    throw new Error(`Unknown item type: ${item.type}`);
  }
  return entry;
}

export function enchantmentLevel(item: Item): number {
  return item.enchantment ?? 0;
}
import { spawnSync } from "node:child_process";
import { describe, expect, it } from "vitest";

function runCli(input: unknown) {
  const { status, stdout, stderr } = spawnSync("node_modules/.bin/tsx", ["src/cli.ts"], {
    input: JSON.stringify(input),
    encoding: "utf8",
  });
  return { status, stdout, stderr };
}

const swordPolicy = { op: "quote", items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }] };
const claimOnFirstPolicy = (damages: { itemType: string; amount: number }[]) => ({
  op: "claim",
  policy: 0,
  incident: { cause: "dragon attack", damages },
});

function expectRejected(result: ReturnType<typeof runCli>, message: RegExp) {
  expect(result.status).not.toBe(0);
  expect(result.stderr).toMatch(message);
  expect(result.stdout).toBe("");
}

describe("claim-office CLI", () => {
  it("schema example (5 years, silver amulet quote + fire claim 200) -> stdout {results:[{premium:59},{payout:100,remainingCap:1100}]}, exit 0", () => {
    const { status, stdout } = runCli({
      customer: { yearsWithMHPCO: 5 },
      steps: [
        { op: "quote", items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }] },
        { op: "claim", policy: 0, incident: { cause: "fire", damages: [{ itemType: "amulet", amount: 200 }] } },
      ],
    });
    expect(status).toBe(0);
    expect(JSON.parse(stdout)).toEqual({ results: [{ premium: 59 }, { payout: 100, remainingCap: 1100 }] });
  });
  it("unknown item type 'broomstick' -> non-zero exit, error on stderr, no results on stdout", () => {
    const result = runCli({ customer: { yearsWithMHPCO: 0 }, steps: [{ op: "quote", items: [{ type: "broomstick" }] }] });
    expectRejected(result, /broomstick/);
  });
  it.todo("damage for an item not in the policy -> non-zero exit, error on stderr, no results on stdout");
  it.todo("more sword damages than insured swords -> non-zero exit, error on stderr, no results on stdout");
  it.todo("damage amount -200 -> non-zero exit, error on stderr, no results on stdout");
});
